mapper.select:
SELECT x.user_id AS userId, x.event_type AS eventType, DATE_FORMAT(x.event_time, '%Y-%m-%d %H:%i:%s') AS eventTime FROM ( SELECT CONVERT(CAST(e.user_id AS CHAR) USING utf8mb4) COLLATE utf8mb4_general_ci AS user_id, CONVERT(e.event_type USING utf8mb4) COLLATE utf8mb4_general_ci AS event_type, e.event_time AS event_time FROM ${database.prefix.userms}hou_user_behavior_event e WHERE e.event_time >= #{from} AND e.event_time < #{to}
UNION ALL
SELECT CONVERT(CAST(l.user_id AS CHAR) USING utf8mb4) COLLATE utf8mb4_general_ci, CONVERT('login' USING utf8mb4) COLLATE utf8mb4_general_ci, l.create_time FROM hou_log_login l WHERE l.login_status = 1 AND l.user_id IS NOT NULL AND l.user_id <> '' AND l.create_time >= #{from} AND l.create_time < #{to}
UNION ALL
SELECT CONVERT(CAST(f.user_id AS CHAR) USING utf8mb4) COLLATE utf8mb4_general_ci, CONVERT('view' USING utf8mb4) COLLATE utf8mb4_general_ci, f.footprint_time FROM ${database.prefix.goods}hou_goods_user_footprint f WHERE f.user_id IS NOT NULL AND f.user_id <> '' AND f.footprint_time IS NOT NULL AND f.footprint_time >= #{from} AND f.footprint_time < #{to}
UNION ALL
SELECT CONVERT(CAST(o.buyer_user_id AS CHAR) USING utf8mb4) COLLATE utf8mb4_general_ci, CONVERT('order' USING utf8mb4) COLLATE utf8mb4_general_ci, o.order_create_time FROM ${database.prefix.order}hou_order_base o WHERE o.buyer_user_id IS NOT NULL AND o.buyer_user_id <> '0' AND o.order_create_time >= #{from} AND o.order_create_time < #{to} ) x ORDER BY x.event_time LIMIT 200000
